1	// Package fsstore is a reference, test-only persistent checkpoint backend that
2	// stores checkpoints as JSON files on disk. It exists to exercise the pluggable
3	// backend seam (registry + mirror fan-out) with a real, non-git implementation
4	// of the api/checkpoint contract, and to serve as a worked example for new
5	// backends.
6	//
7	// It is deliberately NOT registered by production code: only RegisterForTesting
8	// wires it into the checkpoint registry, so a production binary can never select
9	// it. As a mirror it receives best-effort write fan-out; it intentionally ignores
10	// the git-specific blob-hash fields of the contract and stores transcript bytes
11	// directly, which keeps the example small and makes the contract's remaining
12	// git leakage concrete.
13	//
14	// It is faithful to the contract's per-session metadata and write-request
15	// semantics — including prompt and summary redaction via the shared
16	// checkpoint helpers — but it does not replicate two git-writer behaviors:
17	// cross-session aggregation (the root summary's TokenUsage reflects the latest
18	// session, not a sum) and derived stamps the git writer adds (CLI version,
19	// skill-events version). Neither is needed to validate the pluggable seam.
20	package fsstore
21	
22	import (
23		"context"
24		"encoding/json"
25		"fmt"
26		"os"
27		"path/filepath"
28		"sort"
29		"strings"
30		"sync"
31		"time"
32	
33		cp "github.com/entireio/cli/api/checkpoint"
34		"github.com/entireio/cli/cmd/entire/cli/checkpoint"
35		"github.com/entireio/cli/cmd/entire/cli/checkpoint/id"
36		"github.com/entireio/cli/cmd/entire/cli/jsonutil"
37	)
38	
39	// BackendType is the registry type name for the filesystem reference backend.
40	const BackendType = "fs"
41	
42	// Store is a JSON-file-backed persistent checkpoint store. One file per
43	// checkpoint (<root>/<checkpoint-id>.json) holds the root summary plus all
44	// session content.
45	type Store struct {
46		root string
47		mu   sync.Mutex
48	}
49	
50	// New constructs a filesystem store rooted at dir.
51	func New(dir string) *Store {
52		return &Store{root: dir}
53	}
54	
55	type storedSession struct {
56		SessionID  string      `json:"session_id"`
57		Metadata   cp.Metadata `json:"metadata"`
58		Transcript []byte      `json:"transcript,omitempty"`
59		Prompts    string      `json:"prompts,omitempty"`
60	}
61	
62	type storedCheckpoint struct {
63		Summary  cp.CheckpointSummary `json:"summary"`
64		Sessions []storedSession      `json:"sessions"`
65	}
66	
67	var (
68		_ cp.PersistentStore = (*Store)(nil)
69		_ cp.Writer          = (*Store)(nil)
70	)
71	
72	func (s *Store) path(checkpointID id.CheckpointID) string {
73		return filepath.Join(s.root, string(checkpointID)+".json")
74	}
75	
76	// load reads the stored checkpoint, returning (nil, nil) when it does not exist.
77	func (s *Store) load(checkpointID id.CheckpointID) (*storedCheckpoint, error) {
78		data, err := os.ReadFile(s.path(checkpointID))
79		if err != nil {
80			if os.IsNotExist(err) {
81				return nil, nil //nolint:nilnil // absent checkpoint, not an error
82			}
83			return nil, fmt.Errorf("fsstore: read %s: %w", checkpointID, err)
84		}
85		var sc storedCheckpoint
86		if err := json.Unmarshal(data, &sc); err != nil {
87			return nil, fmt.Errorf("fsstore: parse %s: %w", checkpointID, err)
88		}
89		return &sc, nil
90	}
91	
92	func (s *Store) save(sc *storedCheckpoint) error {
93		if err := os.MkdirAll(s.root, 0o750); err != nil {
94			return fmt.Errorf("fsstore: create root %s: %w", s.root, err)
95		}
96		data, err := json.MarshalIndent(sc, "", "  ")
97		if err != nil {
98			return fmt.Errorf("fsstore: encode %s: %w", sc.Summary.CheckpointID, err)
99		}
100		// Write atomically via the shared helper (unique temp file, cleaned up on
101		// failure) so a reader never observes a partial document. This guards a
102		// single writer's in-progress write; cross-process concurrency is out of
103		// scope for this test-only backend.
104		if err := jsonutil.WriteFileAtomic(s.path(sc.Summary.CheckpointID), data, 0o600); err != nil {
105			return fmt.Errorf("fsstore: write %s: %w", sc.Summary.CheckpointID, err)
106		}
107		return nil
108	}
109	
110	// Write dispatches on the request type, mirroring the git store's Write.
111	func (s *Store) Write(_ context.Context, req cp.WriteRequest) error {
112		s.mu.Lock()
113		defer s.mu.Unlock()
114	
115		switch r := req.(type) {
116		case cp.Session:
117			return s.writeSession(cp.WriteOptions(r))
118		case cp.SessionTranscript:
119			return s.backfillTranscript(cp.UpdateOptions(r))
120		case cp.SessionSummary:
121			return s.writeSessionSummary(r)
122		case cp.CheckpointAttribution:
123			return s.writeAttribution(r)
124		default:
125			return fmt.Errorf("fsstore: unsupported write request %T", req)
126		}
127	}
128	
129	func (s *Store) writeSession(opts cp.WriteOptions) error {
130		sc, err := s.load(opts.CheckpointID)
131		if err != nil {
132			return err
133		}
134		if sc == nil {
135			sc = &storedCheckpoint{Summary: cp.CheckpointSummary{CheckpointID: opts.CheckpointID}}
136		}
137	
138		session := storedSession{
139			SessionID:  opts.SessionID,
140			Metadata:   metadataFromWriteOptions(opts),
141			Transcript: opts.Transcript.Bytes(),
142			Prompts:    checkpoint.RedactedJoinedPrompts(opts.Prompts),
143		}
144		sc.Sessions = upsertSession(sc.Sessions, session)
145	
146		// Summary-level flags accumulate across sessions and survive recompute.
147		sc.Summary.HasReview = sc.Summary.HasReview || opts.HasReview
148		sc.Summary.HasInvestigation = sc.Summary.HasInvestigation || opts.HasInvestigation
149		if opts.CombinedAttribution != nil {
150			// Migration path: an initial write may carry holistic attribution. Normal
151			// condensation sets this later via a CheckpointAttribution write instead.
152			sc.Summary.CombinedAttribution = opts.CombinedAttribution
153		}
154	
155		recomputeSummary(sc)
156		return s.save(sc)
157	}
158	
159	func (s *Store) backfillTranscript(opts cp.UpdateOptions) error {
160		sc, err := s.load(opts.CheckpointID)
161		if err != nil {
162			return err
163		}
164		if sc == nil {
165			return fmt.Errorf("fsstore: cannot backfill transcript for unknown checkpoint %s", opts.CheckpointID)
166		}
167		idx := sessionIndexByID(sc.Sessions, opts.SessionID)
168		if idx < 0 {
169			return fmt.Errorf("fsstore: cannot backfill transcript for unknown session %q in %s", opts.SessionID, opts.CheckpointID)
170		}
171		// Replace semantics, but do not clobber sibling fields (matches the git
172		// store's stop-time transcript backfill).
173		sc.Sessions[idx].Transcript = opts.Transcript.Bytes()
174		sc.Sessions[idx].Prompts = checkpoint.RedactedJoinedPrompts(opts.Prompts)
175		if len(opts.SkillEvents) > 0 {
176			sc.Sessions[idx].Metadata.SkillEvents = opts.SkillEvents
177		}
178		return s.save(sc)
179	}
180	
181	func (s *Store) writeSessionSummary(r cp.SessionSummary) error {
182		sc, err := s.load(r.CheckpointID)
183		if err != nil {
184			return err
185		}
186		if sc == nil || len(sc.Sessions) == 0 {
187			return fmt.Errorf("fsstore: cannot set summary for unknown checkpoint %s", r.CheckpointID)
188		}
189		sc.Sessions[len(sc.Sessions)-1].Metadata.Summary = checkpoint.RedactSummary(r.Summary)
190		return s.save(sc)
191	}
192	
193	func (s *Store) writeAttribution(r cp.CheckpointAttribution) error {
194		sc, err := s.load(r.CheckpointID)
195		if err != nil {
196			return err
197		}
198		if sc == nil {
199			return fmt.Errorf("fsstore: cannot set attribution for unknown checkpoint %s", r.CheckpointID)
200		}
201		sc.Summary.CombinedAttribution = r.Attribution
202		return s.save(sc)
203	}
204	
205	// Read returns the checkpoint summary, or (nil, nil) when absent so the
206	// contract helper normalizes it to ErrCheckpointNotFound.
207	func (s *Store) Read(_ context.Context, checkpointID id.CheckpointID) (*cp.CheckpointSummary, error) {
208		s.mu.Lock()
209		defer s.mu.Unlock()
210		sc, err := s.load(checkpointID)
211		if err != nil || sc == nil {
212			return nil, err
213		}
214		summary := sc.Summary
215		return &summary, nil
216	}
217	
218	func (s *Store) List(_ context.Context) ([]cp.CheckpointInfo, error) {
219		s.mu.Lock()
220		defer s.mu.Unlock()
221	
222		entries, err := os.ReadDir(s.root)
223		if err != nil {
224			if os.IsNotExist(err) {
225				return nil, nil
226			}
227			return nil, fmt.Errorf("fsstore: list %s: %w", s.root, err)
228		}
229	
230		var infos []cp.CheckpointInfo
231		for _, e := range entries {
232			if e.IsDir() || !strings.HasSuffix(e.Name(), ".json") {
233				continue
234			}
235			checkpointID := id.CheckpointID(strings.TrimSuffix(e.Name(), ".json"))
236			sc, err := s.load(checkpointID)
237			if err != nil {
238				return nil, err
239			}
240			if sc == nil {
241				continue
242			}
243			infos = append(infos, infoFromStored(sc))
244		}
245		sort.Slice(infos, func(i, j int) bool { return infos[i].CreatedAt.After(infos[j].CreatedAt) })
246		return infos, nil
247	}
248	
249	func (s *Store) ReadSessionContent(_ context.Context, checkpointID id.CheckpointID, sessionIndex int) (*cp.SessionContent, error) {
250		s.mu.Lock()
251		defer s.mu.Unlock()
252		session, err := s.sessionAt(checkpointID, sessionIndex)
253		if err != nil {
254			return nil, err
255		}
256		return &cp.SessionContent{
257			Metadata:   session.Metadata,
258			Transcript: session.Transcript,
259			Prompts:    session.Prompts,
260		}, nil
261	}
262	
263	func (s *Store) ReadSessionMetadata(_ context.Context, checkpointID id.CheckpointID, sessionIndex int) (*cp.Metadata, error) {
264		s.mu.Lock()
265		defer s.mu.Unlock()
266		session, err := s.sessionAt(checkpointID, sessionIndex)
267		if err != nil {
268			return nil, err
269		}
270		meta := session.Metadata
271		return &meta, nil
272	}
273	
274	func (s *Store) ReadSessionPrompts(_ context.Context, checkpointID id.CheckpointID, sessionIndex int) (string, error) {
275		s.mu.Lock()
276		defer s.mu.Unlock()
277		session, err := s.sessionAt(checkpointID, sessionIndex)
278		if err != nil {
279			return "", err
280		}
281		return session.Prompts, nil
282	}
283	
284	func (s *Store) ReadSessionMetadataAndPrompts(_ context.Context, checkpointID id.CheckpointID, sessionIndex int) (*cp.Metadata, string, error) {
285		s.mu.Lock()
286		defer s.mu.Unlock()
287		session, err := s.sessionAt(checkpointID, sessionIndex)
288		if err != nil {
289			return nil, "", err
290		}
291		meta := session.Metadata
292		return &meta, session.Prompts, nil
293	}
294	
295	func (s *Store) sessionAt(checkpointID id.CheckpointID, sessionIndex int) (*storedSession, error) {
296		sc, err := s.load(checkpointID)
297		if err != nil {
298			return nil, err
299		}
300		if sc == nil {
301			return nil, cp.ErrCheckpointNotFound
302		}
303		if sessionIndex < 0 || sessionIndex >= len(sc.Sessions) {
304			return nil, fmt.Errorf("fsstore: session index %d out of range for %s (%d sessions)", sessionIndex, checkpointID, len(sc.Sessions))
305		}
306		return &sc.Sessions[sessionIndex], nil
307	}
308	
309	func metadataFromWriteOptions(opts cp.WriteOptions) cp.Metadata {
310		createdAt := opts.CreatedAt
311		if createdAt.IsZero() {
312			// Contract: a zero CreatedAt means "use the current time".
313			createdAt = time.Now()
314		}
315		return cp.Metadata{
316			CheckpointID:                opts.CheckpointID,
317			SessionID:                   opts.SessionID,
318			Strategy:                    opts.Strategy,
319			CreatedAt:                   createdAt,
320			Branch:                      opts.Branch,
321			CheckpointsCount:            opts.CheckpointsCount,
322			SaveStepCount:               opts.SaveStepCount,
323			FilesTouched:                opts.FilesTouched,
324			Agent:                       opts.Agent,
325			Model:                       opts.Model,
326			TurnID:                      opts.TurnID,
327			IsTask:                      opts.IsTask,
328			ToolUseID:                   opts.ToolUseID,
329			TranscriptIdentifierAtStart: opts.TranscriptIdentifierAtStart,
330			CheckpointTranscriptStart:   opts.CheckpointTranscriptStart,
331			TranscriptLinesAtStart:      opts.CheckpointTranscriptStart, // git writes both for back-compat
332			TokenUsage:                  opts.TokenUsage,
333			SkillEvents:                 opts.SkillEvents,
334			PromptAttributions:          opts.PromptAttributionsJSON,
335			SessionMetrics:              opts.SessionMetrics,
336			Summary:                     checkpoint.RedactSummary(opts.Summary),
337			Attribution:                 opts.Attribution,
338			Kind:                        opts.Kind,
339			ReviewSkills:                opts.ReviewSkills,
340			ReviewPrompt:                opts.ReviewPrompt,
341			InvestigateRunID:            opts.InvestigateRunID,
342			InvestigateTopic:            opts.InvestigateTopic,
343		}
344	}
345	
346	func upsertSession(sessions []storedSession, session storedSession) []storedSession {
347		if idx := sessionIndexByID(sessions, session.SessionID); idx >= 0 {
348			sessions[idx] = session
349			return sessions
350		}
351		return append(sessions, session)
352	}
353	
354	func sessionIndexByID(sessions []storedSession, sessionID string) int {
355		for i := range sessions {
356			if sessions[i].SessionID == sessionID {
357				return i
358			}
359		}
360		return -1
361	}
362	
363	// recomputeSummary rebuilds the aggregated root summary from the sessions, so a
364	// reader sees one Sessions entry per stored session and aggregate counts.
365	func recomputeSummary(sc *storedCheckpoint) {
366		summary := &sc.Summary
367		summary.Sessions = make([]cp.SessionFilePaths, len(sc.Sessions))
368		summary.CheckpointsCount = 0
369		files := map[string]struct{}{}
370		var orderedFiles []string
371	
372		for i := range sc.Sessions {
373			session := &sc.Sessions[i]
374			summary.Sessions[i] = cp.SessionFilePaths{
375				Metadata:   fmt.Sprintf("%d/metadata.json", i+1),
376				Transcript: fmt.Sprintf("%d/full.jsonl", i+1),
377				Prompt:     fmt.Sprintf("%d/prompt.txt", i+1),
378			}
379			summary.CheckpointsCount += session.Metadata.CheckpointsCount
380			if session.Metadata.Strategy != "" {
381				summary.Strategy = session.Metadata.Strategy
382			}
383			if session.Metadata.Branch != "" {
384				summary.Branch = session.Metadata.Branch
385			}
386			if session.Metadata.TokenUsage != nil {
387				summary.TokenUsage = session.Metadata.TokenUsage
388			}
389			for _, f := range session.Metadata.FilesTouched {
390				if _, seen := files[f]; !seen {
391					files[f] = struct{}{}
392					orderedFiles = append(orderedFiles, f)
393				}
394			}
395		}
396		summary.FilesTouched = orderedFiles
397	}
398	
399	func infoFromStored(sc *storedCheckpoint) cp.CheckpointInfo {
400		info := cp.CheckpointInfo{
401			CheckpointID:     sc.Summary.CheckpointID,
402			CheckpointsCount: sc.Summary.CheckpointsCount,
403			FilesTouched:     sc.Summary.FilesTouched,
404			SessionCount:     len(sc.Sessions),
405		}
406		if n := len(sc.Sessions); n > 0 {
407			last := sc.Sessions[n-1]
408			info.SessionID = last.SessionID
409			info.CreatedAt = last.Metadata.CreatedAt
410			info.Agent = last.Metadata.Agent
411			info.IsTask = last.Metadata.IsTask
412			info.ToolUseID = last.Metadata.ToolUseID
413		}
414		info.SessionIDs = make([]string, 0, len(sc.Sessions))
415		for i := range sc.Sessions {
416			info.SessionIDs = append(info.SessionIDs, sc.Sessions[i].SessionID)
417		}
418		return info
419	}
420

