91		if err := s.repo.Storer.SetReference(plumbing.NewHashReference(refName, hash)); err != nil {
92			return fmt.Errorf("set checkpoint ref %s to %s: %w", refName, hash, err)
93		}
94		s.enqueueForPush(ctx, refName)
95		return nil
96	}
97	
98	// enqueueForPush records refName in the push-discovery queue, logging (never
99	// returning) on failure so the local ref write still succeeds.
100	func (s *gitRefsStore) enqueueForPush(ctx context.Context, refName plumbing.ReferenceName) {
101		q, err := PushQueueForRepo(ctx, s.repo)
102		if err != nil {
103			logging.Warn(ctx, "checkpoint: resolve push queue failed; ref not enqueued",
104				slog.String("ref", refName.String()), slog.String("error", err.Error()))
105			return
106		}
107		if err := q.Enqueue(refName); err != nil {
108			logging.Warn(ctx, "checkpoint: enqueue checkpoint ref for push failed",
109				slog.String("ref", refName.String()), slog.String("error", err.Error()))
110		}
111	}
