114		if opts.CheckpointID.IsEmpty() {
115			return errors.New("invalid checkpoint options: checkpoint ID is required")
116		}
117		if err := validation.ValidateSessionID(opts.SessionID); err != nil {
118			return fmt.Errorf("invalid checkpoint options: %w", err)
119		}
120		if err := validation.ValidateToolUseID(opts.ToolUseID); err != nil {
121			return fmt.Errorf("invalid checkpoint options: %w", err)
122		}
123		if err := validation.ValidateAgentID(opts.AgentID); err != nil {
124			return fmt.Errorf("invalid checkpoint options: %w", err)
125		}
126	
127		parentHash, existing, err := s.refBase(opts.CheckpointID)
128		if err != nil {
129			return err
130		}
131	
132		checkpointSubtree, taskMetadataPath, err := s.applySessionWrite(ctx, opts, existing, "", CheckpointVersionRefsV1)
133		if err != nil {
