135		}
136	
137		commitMsg := s.buildCommitMessage(opts, taskMetadataPath)
138		commitHash, err := CreateCommit(ctx, s.repo, checkpointSubtree, parentHash, commitMsg, opts.AuthorName, opts.AuthorEmail)
139		if err != nil {
140			return err
141		}
142		return s.setRef(ctx, opts.CheckpointID, commitHash)
143	}
